-- Nueve plantillas: borradores, versiones finales, correcciones y registro de consultas.
-- Ejecutar después de 003. No modifica historias ni actas existentes.
begin;
create table public.medical_form_templates(id text primary key, definition jsonb not null);
alter table public.medical_form_templates enable row level security;
revoke all on public.medical_form_templates from public,anon,authenticated;
-- Definiciones de los campos, validadas también al guardar directamente en SQL.
insert into public.medical_form_templates values ('historia','{"id":"historia","title":"Historia clínica","description":"Atención individual con los nueve apartados del formato original.","kind":"ficha","period":"date","sections":[{"title":"1. Datos de identificación","fields":[{"key":"paternal","label":"Apellido paterno","type":"text","required":false},{"key":"maternal","label":"Apellido materno","type":"text","required":false},{"key":"names","label":"Nombres","type":"text","required":false},{"key":"date","label":"Fecha","type":"date","required":true},{"key":"time","label":"Hora","type":"time","required":false},{"key":"birthDate","label":"Fecha de nacimiento","type":"date","required":false},{"key":"age","label":"Edad","type":"number","required":false},{"key":"civilStatus","label":"Estado civil","type":"text","required":false},{"key":"department","label":"Gerencia","type":"text","required":false},{"key":"occupation","label":"Profesión - ocupación","type":"text","required":false},{"key":"company","label":"Empresa","type":"text","required":false},{"key":"address","label":"Domicilio","type":"text","required":false},{"key":"phone","label":"Teléfono - celular","type":"text","required":false}]},{"title":"2. Antecedentes personales (hábitos y costumbres)","fields":[{"key":"personalHistory","label":"Antecedentes personales","type":"textarea","required":false}]},{"title":"3. Antecedentes ocupacionales","fields":[{"key":"occupationalHistory","label":"Antecedentes ocupacionales","type":"textarea","required":false}]},{"title":"4. Antecedentes familiares","fields":[{"key":"familyHistory","label":"Antecedentes familiares","type":"textarea","required":false}]},{"title":"5. Motivo de consulta","fields":[{"key":"reason","label":"Motivo de consulta","type":"textarea","required":true}]},{"title":"6. Enfermedad actual","fields":[{"key":"illness","label":"Enfermedad actual","type":"textarea","required":false}]},{"title":"7. Examen físico","fields":[{"key":"bloodPressure","label":"Presión arterial (mmHg)","type":"text","required":false},{"key":"heartRate","label":"Frecuencia cardiaca (lpm)","type":"number","required":false},{"key":"respiratoryRate","label":"Frecuencia respiratoria (rpm)","type":"number","required":false},{"key":"temperature","label":"Temperatura (°C)","type":"number","required":false},{"key":"examination","label":"Examen físico","type":"textarea","required":false}]},{"title":"8. Diagnóstico","fields":[{"key":"diagnosis","label":"Diagnóstico","type":"textarea","required":true}]},{"title":"9. Conducta","fields":[{"key":"conduct","label":"Conducta","type":"textarea","required":false},{"key":"doctor","label":"Médico tratante","type":"text","required":true}]},{"title":"Datos para el registro de consultas","fields":[{"key":"kind","label":"Tipo de atención","type":"select","options":["Consulta","Reconsulta"]},{"key":"workSchedule","label":"Horario de trabajo","type":"text","required":false},{"key":"sex","label":"Sexo","type":"select","options":["F","M"]},{"key":"treatment","label":"Tratamiento","type":"textarea","required":false},{"key":"referral","label":"Interconsulta","type":"textarea","required":false},{"key":"recommendations","label":"Observaciones o recomendaciones","type":"textarea","required":false}]}],"signatures":["Firma del médico","Sello del médico"]}'::jsonb);
insert into public.medical_form_templates values ('consultas','{"id":"consultas","title":"Registro de consultas médicas","description":"Planilla diaria o mensual, con atenciones incorporadas desde Historia clínica.","kind":"planilla","period":"month","sections":[],"columns":[{"key":"date","label":"Fecha","type":"date","required":true},{"key":"time","label":"Hora","type":"time","required":false},{"key":"workSchedule","label":"Horario de trabajo","type":"text","required":false},{"key":"paternal","label":"Apellido paterno","type":"text","required":false},{"key":"maternal","label":"Apellido materno","type":"text","required":false},{"key":"names","label":"Nombres","type":"text","required":false},{"key":"sex","label":"Sexo","type":"select","options":["F","M"]},{"key":"age","label":"Edad","type":"number","required":false},{"key":"diagnosis","label":"Diagnóstico","type":"textarea","required":false},{"key":"kind","label":"Consulta / Reconsulta","type":"select","options":["Consulta","Reconsulta"]},{"key":"treatment","label":"Tratamiento","type":"textarea","required":false},{"key":"doctorSignature","label":"Firma médico","type":"text","required":false},{"key":"patientSignature","label":"Firma paciente","type":"text","required":false},{"key":"referral","label":"Interconsulta","type":"textarea","required":false},{"key":"recommendations","label":"Observaciones o recomendaciones","type":"textarea","required":false}]}'::jsonb);
