insert into public.medical_form_templates values ('periodica','{"id":"periodica","title":"Historia clínica periódica ocupacional","description":"Evaluación ocupacional completa, conservando cada revisión anterior.","kind":"ficha","period":"date","sections":[{"title":"1. Datos de identificación general","fields":[{"key":"fullName","label":"Apellidos y nombres","type":"text","required":true},{"key":"ci","label":"CI","type":"text","required":false},{"key":"birthDate","label":"Fecha de nacimiento","type":"date","required":false},{"key":"sex","label":"Sexo","type":"select","options":["F","M"]},{"key":"age","label":"Edad","type":"number","required":false},{"key":"civilStatus","label":"Estado civil","type":"text","required":false},{"key":"education","label":"Grado de instrucción","type":"text","required":false},{"key":"address","label":"Domicilio actual","type":"text","required":false},{"key":"company","label":"Razón social / empresa","type":"text","required":false},{"key":"nit","label":"NIT","type":"text","required":false},{"key":"occupation","label":"Puesto de trabajo actual","type":"text","required":false},{"key":"department","label":"Área / centro","type":"text","required":false},{"key":"date","label":"Fecha de evaluación","type":"date","required":true},{"key":"previousDate","label":"Fecha examen anterior","type":"date","required":false}]},{"title":"2. Anamnesis y evolución de síntomas","fields":[{"key":"timeInPosition","label":"Tiempo en el puesto actual","type":"text","required":false},{"key":"changedDuties","label":"Cambios en funciones","type":"select","options":["Sí","No"]},{"key":"tasks","label":"Descripción resumida de tareas actuales","type":"textarea","required":false},{"key":"newSymptoms","label":"Síntoma, molestia o signo nuevo desde la última evaluación","type":"select","options":["Sí","No"]},{"key":"symptoms","label":"Especifique","type":"textarea","required":false},{"key":"improvesOutside","label":"Los síntomas mejoran fuera de la jornada laboral","type":